INSERT INTO public.seed_meals (id, name, category, tags, servings, prep_time, cook_time, instructions) VALUES
  ('d91d1fef-084b-4501-9012-967a1024c70f', 'Burgers', 'Beef', '{}', '4', '10 min', '15 min', ARRAY['Divide beef into 4 equal patties, season both sides with salt, pepper, and garlic powder.', 'Heat grill or skillet over medium-high. Cook patties 3–4 min per side for medium doneness.', 'Add cheese in the last minute and cover to melt.', 'Toast buns, assemble with desired toppings.']::text[]),
  ('40e581c4-2469-497b-bfd4-5e91f6098308', 'Burger and Rice', 'Beef', '{}', '4', '5 min', '20 min', ARRAY['Cook rice according to package directions.', 'Brown ground beef in a skillet over medium-high heat; drain fat.', 'Stir in seasoning and diced tomatoes if using; simmer 5 min.', 'Serve beef mixture over rice.']::text[]),
  ('aa4d431f-4b09-4ff0-911d-cec59101b1e3', 'Sloppy Joes', 'Beef', '{}', '6', '5 min', '20 min', ARRAY['Brown ground beef and onion in a skillet; drain fat.', 'Stir in sloppy joe sauce and simmer 10 min.', 'Spoon onto toasted buns.']::text[]),
  ('d5f427ab-eac1-4557-89c7-2972f1160117', 'Spaghetti', 'Beef', '{}', '6', '10 min', '30 min', ARRAY['Cook spaghetti in salted boiling water; drain.', 'Brown beef with onion and garlic; drain fat.', 'Add marinara, simmer 15 min.', 'Serve sauce over pasta with parmesan.']::text[]),
  ('cfaf83a0-54ff-4140-bca9-d7951fa133ee', 'Ravioli', 'Beef', '{}', '4', '5 min', '15 min', ARRAY['For canned: heat in saucepan over medium, stirring occasionally, 8–10 min.', 'For frozen: boil ravioli per package, drain, top with warmed marinara and cheese.']::text[]),
  ('d746b6c7-6840-47b1-bad3-deeb6aa29e4d', 'Lasagna', 'Beef', '{}', '8', '30 min', '60 min', ARRAY['Preheat oven to 375°F. Brown beef; drain. Stir into marinara.', 'Mix ricotta, egg, and half the mozzarella.', 'Layer: sauce, noodles, ricotta mix, mozzarella. Repeat; top with sauce and remaining mozzarella.', 'Cover with foil, bake 45 min; uncover last 10 min. Rest 10 min before cutting.']::text[]),
  ('e552f089-2993-483b-9a02-494cf425d362', 'Lasagna Soup', 'Beef', '{}', '6', '10 min', '30 min', ARRAY['Brown beef in a large pot; drain fat.', 'Add broth, crushed tomatoes, and Italian seasoning. Bring to a boil.', 'Add broken noodles; cook 10–12 min until tender.', 'Ladle into bowls; top with a dollop of ricotta and mozzarella.']::text[]),
  ('d2a7a86b-eb8b-4222-a79f-752af1949318', 'Chili', 'Beef', '{}', '8', '10 min', '45 min', ARRAY['Brown beef and onion in a large pot; drain fat.', 'Add tomatoes, tomato sauce, beans, and all spices.', 'Bring to boil, reduce heat, simmer 30–40 min.', 'Serve with shredded cheese, sour cream, and crackers.']::text[]),
  ('d8f1ad14-151d-43a2-b09a-87b91fefd546', 'Vegetable Soup', 'Beef', '{}', '8', '15 min', '60 min', ARRAY['Brown beef in a large pot over medium-high; remove and set aside.', 'Add broth, tomatoes, carrots, potatoes, and celery. Return beef.', 'Bring to boil, reduce heat, simmer 45 min until beef is tender.', 'Add green beans last 10 min. Season with salt and pepper.']::text[]),
  ('b5314c9f-da4e-4537-a491-2ee2072afeb5', 'Beef Stew', 'Beef', '{}', '6', '20 min', '90 min', ARRAY['Toss beef in flour, salt, and pepper. Brown in batches in a Dutch oven.', 'Add onion, broth, tomato paste; bring to a boil.', 'Reduce heat, cover, simmer 1 hour.', 'Add potatoes and carrots; cook 30 more min until tender.']::text[]),
  ('dae799e0-d42b-4a4f-8c42-a5ca8e0d4409', 'Pot Roast', 'Beef', '{}', '6', '15 min', '480 min', ARRAY['Season roast with salt and pepper; sear in a skillet over high heat.', 'Place in slow cooker. Add onion, broth, and soup mix.', 'Cook on Low 8 hours (or High 4–5 hours).', 'Add potatoes and carrots halfway through cooking.']::text[]),
  ('687c0eb7-38e5-4de2-9f56-5547f81f1e07', 'Cube Steak', 'Beef', '{}', '4', '10 min', '25 min', ARRAY['Season steaks with salt and pepper; dredge in flour.', 'Brown in oil over medium-high, 3 min per side; remove.', 'Sauté onion in same pan. Whisk in remaining flour and broth; bring to a boil.', 'Return steaks, cover, simmer 20 min until tender.']::text[]),
  ('8dc75650-e493-4eb9-9620-e02b0fae58aa', 'Steak Bites', 'Beef', '{}', '4', '10 min', '10 min', ARRAY['Pat steak dry; season with salt and pepper.', 'Heat a cast iron skillet over high; sear steak bites in a single layer 1–2 min per side.', 'Reduce heat, add butter and garlic; baste steak bites 1 min.', 'Drizzle with Worcestershire, garnish with parsley.']::text[]),
  ('815f7acf-669b-495f-aa27-f282fe1a9934', 'Beef and Noodles', 'Beef', '{}', '6', '10 min', '90 min', ARRAY['Brown beef with onion in a pot; drain excess fat.', 'Add broth and cream of mushroom; bring to boil.', 'Reduce heat, simmer covered 60–75 min until beef is tender.', 'Cook egg noodles separately; serve beef and gravy over noodles.']::text[]),
  ('6dcab6aa-1e6d-4188-875f-a6c8a5a9cb6c', 'Hamburger Gravy', 'Beef', '{}', '4', '5 min', '20 min', ARRAY['Brown beef and onion in a skillet; drain most fat, leaving about 2 tbsp.', 'Sprinkle flour over beef, stir to coat, cook 1 min.', 'Gradually whisk in broth; simmer until thickened, about 5–8 min.', 'Season with salt and pepper. Serve over mashed potatoes or toast.']::text[]),
  ('719d72c9-9d51-46d8-81c5-5180aa18749e', 'Round Steak and Gravy', 'Beef', '{}', '4', '10 min', '480 min', ARRAY['Place round steak in slow cooker.', 'Whisk together mushroom soup, broth, and onion soup mix; pour over steak.', 'Cook on Low 7–8 hours until fork-tender.', 'Serve over mashed potatoes or egg noodles.']::text[]),
  ('3fedf7dd-e9ed-4f9f-8633-d2af272ae02e', 'Taco - Traditional', 'Beef', '{}', '6', '10 min', '15 min', ARRAY['Brown ground beef; drain fat.', 'Add taco seasoning and ¾ cup water; simmer until thickened.', 'Warm corn tortillas on a dry skillet or open flame.', 'Top with beef, onion, cilantro, salsa, and a squeeze of lime.']::text[]),
  ('07dc91b6-adc7-42dd-809c-bf084c7dfce5', 'Taco - American', 'Beef', '{}', '6', '10 min', '15 min', ARRAY['Brown ground beef; drain fat. Add taco seasoning and ¾ cup water; simmer.', 'Warm taco shells in oven at 325°F for 5 min.', 'Fill shells with beef, then top with cheese, lettuce, tomato, and sour cream.']::text[]),
  ('56cc53eb-05d4-4cf9-ace9-94decbfc11a2', 'Spanish Rice Burritos', 'Beef', '{}', '6', '15 min', '30 min', ARRAY['Cook rice in 2.5 cups broth or water with diced tomatoes and spices.', 'Brown ground beef; drain. Season with cumin and chili powder.', 'Mix beef, rice, and beans together.', 'Spoon into tortillas with cheese; fold and roll into burritos.']::text[]),
  ('167b8c3f-557a-499e-947b-56cf99af3d52', 'Beef Stroganoff', 'Beef', '{}', '6', '10 min', '25 min', ARRAY['Cook egg noodles; drain and set aside.', 'Brown beef with onion and mushrooms; drain fat.', 'Stir in cream of mushroom soup and broth; simmer 10 min.', 'Remove from heat, stir in sour cream. Serve over egg noodles.']::text[]),
  ('6e295509-9af3-433d-9983-0029bd9bd441', 'Cowboy Bean Bake', 'Beef', '{}', '8', '15 min', '90 min', ARRAY['Preheat oven to 350°F. Brown beef and bacon together; drain fat.', 'Combine beef, bacon, all beans, brown sugar, ketchup, mustard, and vinegar in a large baking dish.', 'Stir well, cover with foil, bake 1 hour 15 min.', 'Uncover last 15 min to thicken.']::text[]),
  ('0ca64f87-5f59-47f5-a7a3-691c690a5941', 'Shepards Pie', 'Beef', '{}', '6', '20 min', '35 min', ARRAY['Preheat oven to 375°F. Brown beef with onion; drain.', 'Add tomato paste, broth, and vegetables; simmer 5 min.', 'Transfer to a baking dish; spread mashed potatoes over the top.', 'Bake 25 min until potatoes are lightly golden.']::text[]),
  ('c17c5429-4bb3-42b2-9c45-1588ee4cd7c4', 'Hamburger Mac', 'Beef', '{}', '6', '5 min', '25 min', ARRAY['Brown ground beef in a large skillet; drain.', 'Add broth and macaroni; bring to boil, cover, simmer 10–12 min until pasta is tender.', 'Stir in tomatoes if using; fold in cheese until melted.', 'Season with salt, pepper, and garlic powder.']::text[]),
  ('0de9b1e7-d92e-45f3-a304-120d5fee9101', 'Meatloaf', 'Beef', '{}', '6', '15 min', '60 min', ARRAY['Preheat oven to 350°F.', 'Mix beef, breadcrumbs, eggs, milk, onion, Worcestershire; do not overwork.', 'Form into a loaf in a baking dish; spread ketchup over top.', 'Bake 55–60 min until internal temp reaches 160°F. Rest 10 min before slicing.']::text[]),
  ('255a1371-6346-4ce7-9ef0-6d577af11bb9', 'Johnny', 'Beef', '{}', NULL, NULL, NULL, '{}'),
  ('aa243fe4-ee5b-47a2-b70a-dc4195a2b8e5', 'Country Fried Steak', 'Beef', '{}', '4', '15 min', '20 min', ARRAY['Season steaks with salt and pepper; dredge in flour, dip in egg, dredge in flour again.', 'Fry in hot oil 3–4 min per side until golden; set aside.', 'Pour off all but 3 tbsp oil; whisk in 3 tbsp flour, cook 1 min.', 'Gradually whisk in milk; simmer until thickened into cream gravy. Season well. Serve over steaks.']::text[]),
  ('900a77e3-05a9-4d97-9568-3a764441b901', 'Garlic Parm Beef Rotini', 'Beef', '{}', '6', '10 min', '20 min', ARRAY['Cook rotini in salted water; reserve ½ cup pasta water before draining.', 'Brown beef; drain. Push to the side, melt butter, sauté garlic 1 min.', 'Add drained pasta and reserved pasta water; toss together.', 'Remove from heat, fold in parmesan. Season with salt and pepper.']::text[]),
  ('7063fe6f-8c88-4cab-9340-00ceee3c5c40', 'Crock Pot Taco Rice Soup', 'Beef', '{}', '8', '10 min', '360 min', ARRAY['Add browned beef, tomatoes, corn, beans, broth, and taco seasoning to slow cooker.', 'Cook on Low 6 hours or High 3 hours.', 'Stir in rice during last 30 min of cooking.', 'Serve topped with sour cream, shredded cheese, and tortilla strips.']::text[]),
  ('9b201a65-c287-4f05-8d06-8c1d5d7581db', 'Cheeseburger Soup', 'Beef', '{}', '8', '15 min', '30 min', ARRAY['Brown beef with onion and celery; drain.', 'Add broth and potatoes; bring to boil, simmer 15 min until potatoes are tender.', 'Stir in Velveeta and milk over low heat until melted and smooth.', 'Season with salt and pepper. Top with crumbled bacon or shredded cheese.']::text[]),
  ('ef31abf1-1830-4f0b-b9e5-ccfcfdfa34b4', 'Swedish Meatballs', 'Beef', '{}', '6', '20 min', '30 min', ARRAY['Mix beef, breadcrumbs, egg, salt, pepper, and a pinch of nutmeg; roll into 1-inch meatballs.', 'Brown meatballs in butter; remove and set aside.', 'Whisk flour into pan drippings; gradually add broth, simmer until thickened.', 'Remove from heat, stir in sour cream; return meatballs and heat through. Serve over egg noodles.']::text[]),
  ('47fb5dd1-9adc-4f25-bea3-be8457b6acf6', 'Chicken and a Side', 'Chicken', '{}', NULL, NULL, NULL, '{}'),
  ('74dad7f0-19f9-4ab2-88fa-ec23fcecbb25', 'Stir Fry', 'Chicken', '{}', '4', '15 min', '15 min', ARRAY['Stir together soy sauce, oyster sauce, and sesame oil; set aside.', 'Heat wok or large skillet over high. Cook chicken in batches until golden; remove.', 'Add vegetables and garlic; stir-fry 3–4 min until crisp-tender.', 'Return chicken, pour sauce over, toss 1 min. Serve over rice.']::text[]),
  ('dc889dff-ed92-48f3-85f9-9b6148e86f99', 'Chicken Tacos', 'Chicken', '{}', '6', '10 min', '15 min', ARRAY['Season chicken with taco seasoning.', 'Cook in a skillet with a little oil over medium-high, 6–7 min per side. Rest and shred.', 'Warm tortillas.', 'Fill tortillas with chicken and desired toppings.']::text[]),
  ('240f86c0-e656-4ba7-81ba-92f132877e9a', 'Alfredo', 'Chicken', '{}', '4', '10 min', '25 min', ARRAY['Cook fettuccine; reserve ½ cup pasta water. Drain.', 'Season and cook chicken in butter until cooked through; remove and slice.', 'In same pan, sauté garlic; add heavy cream, simmer 5 min until slightly thickened.', 'Stir in parmesan; toss with pasta and chicken, adding pasta water as needed.']::text[]),
  ('8619b8bc-ede1-43a7-9cd8-6037002ff525', 'Chicken Parm', 'Chicken', '{}', '4', '20 min', '25 min', ARRAY['Dip chicken in egg then breadcrumbs; pan-fry in oil over medium-high 3–4 min per side.', 'Transfer to a baking dish; top each piece with marinara, mozzarella, and parmesan.', 'Bake at 400°F for 15 min until cheese is bubbly.', 'Serve over pasta with extra marinara.']::text[]),
  ('6f0ea51e-8b7f-491e-9723-468ba1aa40d6', 'Pesto Pasta', 'Chicken', '{}', '4', '10 min', '20 min', ARRAY['Cook pasta; reserve ¼ cup pasta water, drain.', 'Season and cook chicken in olive oil until cooked through; slice.', 'Toss warm pasta with pesto, adding pasta water to loosen.', 'Top with chicken, tomatoes, and parmesan.']::text[]),
  ('e80f7e14-f5ce-45e4-aff4-d758968db8cb', 'Chicken Parm Soup', 'Chicken', '{}', '6', '15 min', '30 min', ARRAY['Cook chicken in a large pot with a little oil; season with Italian seasoning.', 'Add broth and crushed tomatoes; bring to boil.', 'Add pasta; cook 10 min until tender.', 'Ladle into bowls; top with mozzarella and parmesan.']::text[]),
  ('791eb89a-0f29-4c25-92d5-03430b397d5e', 'Pot Pie', 'Chicken', '{}', '6', '20 min', '45 min', ARRAY['Preheat oven to 375°F. Mix chicken, vegetables, soup, broth, and sour cream.', 'Line a 9-inch pie dish with one crust; pour in filling.', 'Top with second crust; crimp edges, cut vent slits.', 'Bake 40–45 min until crust is golden. Rest 10 min before serving.']::text[]),
  ('fe4af5b3-6b3c-47cc-8fe6-20894e92e599', 'Chicken and Rice', 'Chicken', '{}', '4', '10 min', '35 min', ARRAY['Preheat oven to 350°F.', 'Mix rice, broth, cream of chicken, and onion in a 9x13 dish.', 'Nestle chicken pieces on top; season generously.', 'Cover tightly with foil; bake 45–50 min until rice is cooked and chicken reaches 165°F.']::text[]),
  ('23a00ed8-eaf1-49ec-adc6-6744ad99ec63', 'Chicken and Noodles', 'Chicken', '{}', '6', '10 min', '60 min', ARRAY['Simmer chicken in broth with celery, carrots, and onion until cooked, about 25 min.', 'Remove chicken; shred.', 'Bring broth back to a boil; add noodles and cook per package directions.', 'Return chicken; season with salt and pepper.']::text[]),
  ('929cb27e-256f-4924-a3e0-0324ba0c50c5', 'Creamy Chicken and Noodles', 'Chicken', '{}', '6', '10 min', '25 min', ARRAY['In a large pot, whisk together cream of chicken soup, sour cream, and broth over medium heat.', 'Stir in chicken, peas, and cooked noodles.', 'Heat through, stirring occasionally, about 10 min.', 'Season with salt and pepper.']::text[]),
  ('8250f43a-aa8f-4dcc-beb5-1a010d46c5b4', 'Garlic Parm Crock Pot Chicken', 'Chicken', '{}', '6', '10 min', '360 min', ARRAY['Place chicken in slow cooker; add garlic, broth, and butter.', 'Cook on Low 6 hours or High 3 hours.', 'Shred chicken; stir in cream cheese and parmesan until smooth.', 'Serve over pasta, mashed potatoes, or rice.']::text[]),
  ('4f13690a-3113-417f-a79f-de5115d8461f', 'Chicken Strips', 'Chicken', '{}', '4', '15 min', '15 min', ARRAY['Season flour; dredge chicken in flour, dip in egg, then coat in breadcrumbs.', 'Pan-fry: cook in oil over medium-high 3–4 min per side until golden and cooked through.', 'Oven: bake at 400°F for 20 min, flipping halfway, until crispy.', 'Serve with dipping sauce.']::text[]),
  ('b7ac0965-13c9-405d-bfd5-a77ff7982eb2', 'Chicken Potato Bake', 'Chicken', '{}', '4', '15 min', '50 min', ARRAY['Preheat oven to 400°F. Toss potatoes and onion with olive oil and seasoning.', 'Spread in a single layer in a large baking pan.', 'Season chicken thighs; nestle among vegetables skin-side up.', 'Bake 45–50 min until chicken skin is crispy and potatoes are tender.']::text[]),
  ('75abe8c0-424b-45ea-b7dd-fa8901bdf4a6', 'Chicken With Garlic Parmesan Rice', 'Chicken', '{}', '4', '10 min', '30 min', ARRAY['Cook rice in chicken broth with garlic and butter; fluff, stir in parmesan.', 'Season chicken; cook in an oven-safe skillet over medium-high 4 min per side.', 'Transfer skillet to 375°F oven; bake 15 min until chicken reaches 165°F.', 'Serve chicken over garlic parmesan rice.']::text[]),
  ('071b5523-e978-496e-8ad5-e365a19de20c', 'Slow Cooker Chicken Chili', 'Chicken', '{}', '8', '10 min', '360 min', ARRAY['Add chicken, beans, chiles, corn, broth, and ranch mix to slow cooker.', 'Cook on Low 6 hours or High 3 hours.', 'Shred chicken with two forks directly in the pot.', 'Stir in cream cheese; cover 20–30 min until melted and smooth.']::text[]),
  ('c05c5724-3fd4-46ed-952f-ec3e471d5aad', 'Chops and Side', 'Pork', '{}', NULL, NULL, NULL, '{}'),
  ('e9e37b28-b6e2-4c56-9c6f-f02abf8e8b85', 'Pork Stir Fry', 'Pork', '{}', '4', '15 min', '15 min', ARRAY['Stir together soy sauce, oyster sauce, and sesame oil.', 'Cook pork in a hot wok or skillet in batches; remove.', 'Stir-fry vegetables and garlic 3–4 min until crisp-tender.', 'Return pork; pour sauce over, toss 1 min. Serve over rice.']::text[]),
  ('5ac6babe-ca96-4d13-9244-947d4091c409', 'Pork Roast', 'Pork', '{}', '8', '15 min', '480 min', ARRAY['Season pork roast generously with salt and pepper.', 'Place in slow cooker; scatter vegetables around.', 'Pour broth over; sprinkle onion soup mix on top.', 'Cook on Low 8 hours; rest before slicing or pulling.']::text[]),
  ('8aa9ddba-6a36-4120-acf6-a229408ec49b', 'Balsamic Pork', 'Pork', '{}', '6', '10 min', '360 min', ARRAY['Whisk balsamic, honey, garlic, and rosemary.', 'Place pork in slow cooker; pour sauce over.', 'Cook on Low 6 hours.', 'Rest pork; slice and spoon cooking juices over. Serve with roasted vegetables or mashed potatoes.']::text[]),
  ('5acb1dd9-7b8e-4fba-b736-edc4440e5478', 'Pulled Pork', 'Pork', '{}', '10', '10 min', '480 min', ARRAY['Mix dry rub (brown sugar, paprika, garlic, onion powder, salt, pepper, cumin); coat pork.', 'Place in slow cooker; cook on Low 8–10 hours until fork-tender.', 'Shred pork in the juices; stir in BBQ sauce.', 'Pile onto buns; top with coleslaw.']::text[]),
  ('d76abe54-b3b8-4460-8e2a-912e180cf91e', 'Smackies', 'Pork', '{}', NULL, NULL, NULL, '{}'),
  ('2ff981de-d193-41d3-82a1-eff91c4af904', 'Pork Cutlets', 'Pork', '{}', '4', '15 min', '15 min', ARRAY['Season pork; dredge in flour, dip in egg, coat in breadcrumbs.', 'Pan-fry in oil over medium-high 3–4 min per side until golden and cooked through.', 'Drain on paper towels.', 'Serve with lemon wedges and a side salad or mashed potatoes.']::text[]),
  ('2495d1b9-87f8-4877-a3da-de0468bbde84', 'BLT', 'Pork', '{}', '4', '10 min', '10 min', ARRAY['Cook bacon until crispy; drain on paper towels.', 'Toast bread.', 'Spread mayo on both slices; layer lettuce, tomato, and bacon.', 'Press together; cut diagonally.']::text[]),
  ('8101dc97-653d-46eb-9c87-35a74a18d440', 'Smoked Pork Chops', 'Pork', '{}', '4', '5 min', '15 min', ARRAY['Pat chops dry; season lightly with salt and pepper.', 'Melt butter in a skillet over medium-high; add garlic.', 'Sear chops 3 min per side, basting with butter.', 'Add brown sugar last minute; let caramelize. Serve with roasted vegetables.']::text[]),
  ('71898d60-b4b6-498e-917e-f1b2b286d6c8', 'Pizza - Order', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('0708000f-2cc9-4528-b4b6-d4c332eee5cd', 'Pizza - Frozen', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('8aab929f-ce8b-40a4-a5ac-de78c87de48c', 'Fish Sandwiches', 'Seafood', '{}', '4', '10 min', '15 min', ARRAY['Dip fish in egg then breadcrumbs; pan-fry in oil over medium-high 3–4 min per side.', 'Or bake at 400°F 15 min, flipping once.', 'Toast buns; spread tartar sauce.', 'Layer fish with lettuce and tomato.']::text[]),
  ('09c873d5-e2f2-40fa-919f-6e32f575a50b', 'Fish Dinner', 'Seafood', '{}', '4', '5 min', '15 min', ARRAY['Preheat oven to 400°F.', 'Place fish in a baking dish; season with salt, pepper, and paprika.', 'Mix butter and garlic; drizzle over fish. Lay lemon slices on top.', 'Bake 12–15 min until fish flakes easily. Garnish with parsley.']::text[]),
  ('9af9c854-e459-46f3-bc07-f6788535cbcf', 'Pancakes', 'Other', '{}', '4', '5 min', '15 min', ARRAY['Whisk dry ingredients together in a bowl.', 'Add milk, egg, and melted butter; stir until just combined (lumps are okay).', 'Pour ¼ cup batter onto a greased griddle over medium heat; cook until bubbles form, then flip.', 'Serve with butter and maple syrup.']::text[]),
  ('fdae88af-7a4c-4eb4-b144-53ee971b7e28', 'Biscuits and Gravy', 'Other', '{}', '6', '10 min', '20 min', ARRAY['Bake or cook biscuits per package directions.', 'Brown sausage in a skillet; do not drain.', 'Sprinkle flour over sausage; stir 1 min. Gradually whisk in milk.', 'Simmer, stirring, until thick. Season with salt and lots of pepper. Spoon over split biscuits.']::text[]),
  ('fc5da96c-0d9d-4bad-8d42-f1e872e7b698', 'French Toast', 'Other', '{}', '4', '5 min', '15 min', ARRAY['Whisk eggs, milk, vanilla, and cinnamon in a shallow bowl.', 'Dip bread slices in egg mixture, coating both sides.', 'Cook in buttered skillet or griddle over medium 2–3 min per side until golden.', 'Serve with maple syrup and powdered sugar.']::text[]),
  ('e390ddb5-3079-4277-b0c2-86898c7aec35', 'Eggs and Ham', 'Other', '{}', '4', '5 min', '10 min', ARRAY['Warm ham slices in a skillet over medium; set aside.', 'Melt butter in same skillet; crack eggs in.', 'Cook sunny-side up, over-easy, or scrambled to preference.', 'Serve eggs alongside ham with buttered toast.']::text[]),
  ('f7b9b05b-29b5-4c1e-9b34-8194668d19cb', 'Garbage', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('7ee185a5-ba95-463b-b3e6-0e17ed78ad90', 'Lunch Meat Sandwiches', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('e489a08e-8103-4b8a-809d-052cd04f899e', 'Pizza Rolls', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('520e01f8-41f3-42fe-b1c4-0dffa54b78bc', 'Turkey Dinner', 'Other', '{}', '10', '30 min', '200 min', ARRAY['Preheat oven to 325°F. Pat turkey dry; mix butter with garlic and herbs.', 'Rub butter under and over skin; season generously with salt and pepper.', 'Roast breast-side up, about 15 min per pound, until thigh reaches 165°F.', 'Rest 30 min before carving. Use pan drippings for gravy.']::text[]),
  ('1c6ad872-0afd-4f16-ad81-015b43f5be2a', 'Ham Dinner', 'Other', '{}', '10', '10 min', '150 min', ARRAY['Preheat oven to 325°F. Place ham cut-side down in a roasting pan; cover with foil.', 'Bake 15 min per pound.', 'Mix brown sugar, honey, Dijon, and spices into a glaze.', 'Brush glaze over ham every 20 min during last hour; uncover for final 20 min.']::text[]),
  ('c3ebb28b-7385-4fb9-a8b0-168894f945d8', 'Philly Cheesesteak', 'Beef', '{}', '4', '15 min', '20 min', ARRAY['Sauté peppers and onion in oil over medium-high until soft; remove.', 'Cook shaved beef in same pan, breaking apart, until cooked through. Season with salt and pepper.', 'Return vegetables to pan; top with provolone, cover 1 min to melt.', 'Pile into hoagie rolls.']::text[]),
  ('95702e08-b967-4d5e-8c4e-1a82eea95a99', 'Beef Enchiladas', 'Beef', '{}', '6', '20 min', '25 min', ARRAY['Preheat oven to 375°F. Brown beef; drain. Add taco seasoning and ¼ cup water.', 'Dip each tortilla briefly in enchilada sauce; fill with beef and cheese, roll up.', 'Place seam-down in a baking dish. Pour remaining sauce over top; add cheese.', 'Bake 20–25 min until bubbly.']::text[]),
  ('ee72ac4a-9ff4-4ad4-ab2c-9b70e522b0b8', 'Beef Fried Rice', 'Beef', '{}', '4', '10 min', '15 min', ARRAY['Brown beef in a large skillet or wok; drain. Add garlic, cook 1 min.', 'Push beef to the side; scramble eggs in the pan.', 'Add rice and frozen vegetables; stir-fry 3–4 min.', 'Drizzle soy sauce and sesame oil; toss to combine.']::text[]),
  ('98ba1e90-c082-4c1e-ad46-a89cd3c49ca5', 'Stuffed Bell Peppers', 'Beef', '{}', '6', '20 min', '40 min', ARRAY['Preheat oven to 375°F. Brown beef; drain. Stir in tomatoes, rice, and seasoning.', 'Stand peppers upright in a baking dish; fill with beef mixture.', 'Top with cheese; add ¼ cup water to the bottom of the dish.', 'Cover with foil; bake 30 min. Uncover last 10 min.']::text[]),
  ('5495cddd-54c5-46c7-b52d-e02e2fef7a3b', 'Beef Fajitas', 'Beef', '{}', '4', '15 min', '15 min', ARRAY['Marinate steak with seasoning, lime juice, and 1 tbsp oil for at least 30 min.', 'Sear steak in a hot cast iron skillet 4–5 min per side; rest 5 min, then slice thin against the grain.', 'Cook peppers and onion in the same skillet until charred and tender.', 'Serve steak and vegetables in warm tortillas with salsa and sour cream.']::text[]),
  ('c5fa450f-129c-4b19-88e6-f53d9d3ee86b', 'Korean Beef Bowl', 'Beef', '{}', '4', '10 min', '15 min', ARRAY['Brown ground beef; drain fat.', 'Stir in garlic and ginger; cook 1 min.', 'Add soy sauce, brown sugar, and sesame oil; stir to combine and simmer 3 min.', 'Serve over rice; garnish with green onion and sesame seeds.']::text[]),
  ('50a7d2b4-209c-454c-8649-670e8d3801c8', 'French Dip Sandwich', 'Beef', '{}', '6', '10 min', '480 min', ARRAY['Place roast in slow cooker; pour broth over and sprinkle soup mix.', 'Cook on Low 8 hours.', 'Shred beef; return to juices.', 'Pile beef onto rolls with provolone; broil 2 min to melt. Serve with broth for dipping.']::text[]),
  ('3ad4c5e9-2ea2-49d5-a793-f4922bfee0ec', 'Patty Melt', 'Beef', '{}', '4', '15 min', '30 min', ARRAY['Caramelize onions in 2 tbsp butter over medium-low heat, 25–30 min.', 'Form beef into 4 thin patties to match bread shape; season with salt and pepper.', 'Cook patties in a skillet 3–4 min per side.', 'Butter bread, build sandwiches with beef, onions, and Swiss; grill until golden on both sides.']::text[]),
  ('6e124e3e-2b79-42bb-b60e-83f00265d0bb', 'Reuben Sandwich', 'Beef', '{}', '4', '5 min', '10 min', ARRAY['Spread Thousand Island on one side of each bread slice.', 'Build sandwiches: bread, cheese, corned beef, sauerkraut, cheese, bread.', 'Butter outer bread; grill in a skillet or griddle over medium until golden, about 3 min per side.']::text[]),
  ('629f757b-fce9-409d-abe8-a9a482f774d4', 'Beef Nachos', 'Beef', '{}', '6', '10 min', '15 min', ARRAY['Preheat oven to 375°F. Brown beef; drain. Add taco seasoning and ¼ cup water.', 'Spread chips on a large baking sheet; layer with beef, beans, and cheese.', 'Bake 8–10 min until cheese is melted.', 'Top with jalapeños, sour cream, and salsa.']::text[]),
  ('78cef025-79a3-49ad-829d-6f6606ead63e', 'Chili Mac', 'Beef', '{}', '8', '10 min', '30 min', ARRAY['Brown beef in a large pot; drain fat.', 'Add tomatoes, beans, broth, and chili powder; bring to boil.', 'Stir in macaroni; reduce heat, simmer 10–12 min until pasta is tender.', 'Top bowls with shredded cheddar.']::text[]),
  ('788fafac-2600-4bf9-8e85-5a2d6b3017df', 'Salisbury Steak', 'Beef', '{}', '4', '15 min', '25 min', ARRAY['Mix beef, breadcrumbs, egg, salt, and pepper; form 4 oval patties.', 'Brown patties in a skillet 3 min per side; remove.', 'Sauté mushrooms; whisk in flour, then broth and Worcestershire. Simmer until thickened.', 'Return patties to gravy; cover and simmer 15 min. Serve over mashed potatoes.']::text[]),
  ('e0977602-de48-4646-8b55-01ec3c84308d', 'Mississippi Pot Roast', 'Beef', '{}', '6', '5 min', '480 min', ARRAY['Place chuck roast in slow cooker.', 'Sprinkle ranch and au jus mixes over roast.', 'Place butter on top; add pepperoncini around the roast.', 'Cook on Low 8 hours; shred beef in the juices before serving.']::text[]),
  ('621d5ba7-7994-4568-929d-a15b2311c61c', 'Birria Tacos', 'Beef', '{}', '8', '30 min', '180 min', ARRAY['Toast dried chiles in a dry skillet; soak in hot water 20 min. Blend with garlic, tomatoes, and spices.', 'Brown beef; add chile sauce and enough water to cover. Simmer covered 2–2.5 hours until beef shreds.', 'Shred beef; reserve consommé (broth) for dipping.', 'Dip tortillas in fat from consommé; fill with beef and cheese, fold, and griddle until crispy. Serve with consommé.']::text[]),
  ('2f041724-39b9-43ee-9d35-54d12ee585f7', 'Carne Asada', 'Beef', '{}', '6', '10 min', '15 min', ARRAY['Whisk together orange juice, lime juice, garlic, cumin, chili powder, and olive oil.', 'Marinate steak at least 2 hours (overnight preferred).', 'Grill over high heat 4–5 min per side; rest 5 min.', 'Slice thin against the grain. Serve in tortillas with salsa, onion, and cilantro.']::text[]),
  ('d646cdb8-a26b-4dfb-b241-59ff4af27775', 'Bolognese', 'Beef', '{}', '6', '15 min', '60 min', ARRAY['Sauté onion, celery, and carrot in olive oil until softened.', 'Add beef and pork; brown thoroughly. Add wine; cook until evaporated.', 'Stir in tomatoes and milk; simmer uncovered 45 min, stirring occasionally.', 'Cook pasta; toss with sauce and parmesan.']::text[]),
  ('75e10401-5ce1-4d02-b423-e03284c7d836', 'Beef Stuffed Shells', 'Beef', '{}', '6', '25 min', '35 min', ARRAY['Preheat oven to 375°F. Brown beef; drain.', 'Mix beef with ricotta, egg, and 1 cup mozzarella.', 'Spread half the marinara in a baking dish; fill shells with beef mixture and place on sauce.', 'Top with remaining marinara and mozzarella. Bake 30 min.']::text[]),
  ('38cf76c0-c351-4a94-9a3a-09964749ba3e', 'Beef Quesadillas', 'Beef', '{}', '4', '10 min', '15 min', ARRAY['Brown beef; drain. Add taco seasoning and ¼ cup water; simmer.', 'Heat a skillet over medium. Place a tortilla in pan; top half with beef and cheese.', 'Fold over; cook 2–3 min per side until golden and cheese is melted.', 'Slice into wedges; serve with salsa and sour cream.']::text[]),
  ('22c7eedd-b3a5-42df-9a8b-d24c94ca45d0', 'Beef Barley Soup', 'Beef', '{}', '8', '15 min', '60 min', ARRAY['Brown beef in a large pot; remove and set aside.', 'Sauté onion, carrots, and celery in same pot until softened.', 'Add broth, tomato paste, beef, and barley; bring to boil.', 'Reduce heat; simmer 45–50 min until beef is tender and barley is cooked.']::text[]),
  ('699b234b-6b7a-44a0-bec3-7e9ebee50543', 'Smash Burgers', 'Beef', '{}', '4', '10 min', '10 min', ARRAY['Divide beef into 8 loosely packed 3-oz balls.', 'Heat a cast iron over high until smoking. Place a ball, smash flat immediately with a spatula.', 'Season with salt; cook 90 sec. Flip; add cheese; cook 60 sec. Stack two patties per bun.', 'Spread sauce on toasted buns; assemble with pickles and onion.']::text[]),
  ('27e5eb20-65ec-4141-ba85-0f4021cc858b', 'Beef Ziti', 'Beef', '{}', '6', '15 min', '35 min', ARRAY['Preheat oven to 375°F. Cook ziti; drain. Brown beef; drain fat.', 'Mix pasta, beef, marinara, and ricotta; transfer to a greased baking dish.', 'Top with mozzarella.', 'Bake 25 min until bubbly and cheese is golden.']::text[]),
  ('b7b10a04-96c4-4a7e-9085-b61dd7082dfd', 'Beef Bulgogi', 'Beef', '{}', '4', '15 min', '10 min', ARRAY['Combine soy sauce, brown sugar, sesame oil, garlic, and grated pear.', 'Marinate sliced beef at least 30 min.', 'Cook in a very hot skillet or grill in batches until caramelized, 2–3 min per side.', 'Serve over rice with kimchi and green onions.']::text[]),
  ('cede5829-d279-4033-b633-fe9c1447db0b', 'Beef Kebabs', 'Beef', '{}', '4', '20 min', '15 min', ARRAY['Marinate beef in olive oil, soy sauce, lemon juice, and garlic for 1 hour.', 'Thread beef, peppers, and onion onto skewers alternating.', 'Grill over medium-high heat, turning every 3–4 min, about 12 min total.', 'Rest 5 min before serving.']::text[]),
  ('b92f45b5-0944-4432-8caa-a018d846af28', 'Stuffed Cabbage Rolls', 'Beef', '{}', '6', '30 min', '90 min', ARRAY['Boil cabbage head until outer leaves can be peeled off; separate 12 leaves.', 'Mix beef, rice, egg, salt, and pepper.', 'Place filling in each leaf; roll tightly tucking in sides.', 'Place in a baking dish; mix tomato soup and diced tomatoes, pour over rolls. Cover; bake at 350°F for 1.5 hours.']::text[]),
  ('9905ea52-9fcf-40a1-a14d-a50dc65334bb', 'Ground Beef Casserole', 'Beef', '{}', '6', '15 min', '30 min', ARRAY['Preheat oven to 350°F. Brown beef and onion; drain.', 'Stir in cream of mushroom soup, sour cream, and cooked noodles.', 'Transfer to a greased baking dish; top with cheddar.', 'Bake 25–30 min until bubbly.']::text[]),
  ('0457e103-2b2d-4ac6-abb5-59311c86ff7d', 'Buffalo Chicken', 'Chicken', '{}', '4', '10 min', '25 min', ARRAY['Cook chicken in oven at 400°F for 20–22 min or pan-fry until cooked through.', 'Whisk buffalo sauce and melted butter together.', 'Toss hot cooked chicken in buffalo sauce.', 'Serve with ranch or blue cheese, celery, and carrots. Use as-is or over rice, in wraps, or on pizza.']::text[]),
  ('e85c3062-6407-46b8-af85-8ed78ad7bc28', 'Chicken Enchiladas', 'Chicken', '{}', '6', '20 min', '25 min', ARRAY['Preheat oven to 375°F. Mix chicken with cream cheese and ¼ cup enchilada sauce.', 'Dip tortillas in sauce; fill with chicken mixture, roll up, place seam-down in dish.', 'Pour remaining sauce over; top with cheese.', 'Bake 20–25 min until bubbly.']::text[]),
  ('9df7187c-7db8-4957-afae-f8faae219caf', 'Chicken Fried Rice', 'Chicken', '{}', '4', '10 min', '15 min', ARRAY['Cook chicken in a hot wok or skillet until golden; add garlic.', 'Push to side; scramble eggs in pan.', 'Add rice and frozen vegetables; stir-fry 3–4 min.', 'Drizzle soy sauce and sesame oil; toss everything together.']::text[]),
  ('f0e94157-34b3-4fb4-a3e3-9a66b79f1cbd', 'Chicken Fajitas', 'Chicken', '{}', '4', '15 min', '15 min', ARRAY['Toss chicken with seasoning and lime juice; let sit 15 min.', 'Cook chicken in a hot skillet over high heat until cooked through; set aside.', 'Cook peppers and onion in same skillet until slightly charred.', 'Serve chicken and vegetables in warm tortillas with sour cream and salsa.']::text[]),
  ('e2f77834-1ca8-4ef6-9192-2ac1dfe5bbd8', 'BBQ Chicken', 'Chicken', '{}', '4', '5 min', '30 min', ARRAY['Season chicken with salt, pepper, and garlic powder.', 'Grill or bake at 400°F 20–25 min, turning once.', 'Brush generously with BBQ sauce the last 5 min of cooking.', 'Rest 5 min before serving.']::text[]),
  ('705473f5-30fa-4df1-933a-e953aec56cc3', 'Honey Garlic Chicken', 'Chicken', '{}', '4', '10 min', '25 min', ARRAY['Season chicken; sear skin-side down in an oven-safe skillet over medium-high 4 min.', 'Flip; add butter, garlic, honey, and soy sauce to pan.', 'Baste chicken; transfer skillet to 400°F oven for 20–25 min.', 'Spoon pan sauce over chicken before serving.']::text[]),
  ('109007f5-a674-487e-adb8-061a592331ed', 'Lemon Pepper Chicken', 'Chicken', '{}', '4', '5 min', '25 min', ARRAY['Preheat oven to 400°F. Season chicken with lemon pepper, garlic powder, and salt.', 'Melt butter in an oven-safe skillet; sear chicken 3 min per side.', 'Top with lemon slices; transfer to oven, bake 15–18 min until 165°F.', 'Rest 5 min; spoon pan juices over before serving.']::text[]),
  ('14a6b682-73ab-43c0-b851-2139a4fd590b', 'Chicken Tikka Masala', 'Chicken', '{}', '6', '20 min', '30 min', ARRAY['Cook onion, garlic, and ginger in oil; stir in spices, cook 1 min.', 'Add tomatoes; simmer 10 min.', 'Add chicken; cook 15 min until cooked through.', 'Stir in cream; simmer 5 min. Serve over basmati rice with naan.']::text[]),
  ('181c59cf-bf5f-400d-947c-4dcadc246828', 'Orange Chicken', 'Chicken', '{}', '4', '15 min', '20 min', ARRAY['Coat chicken in cornstarch; fry in oil over medium-high until crispy, about 5 min. Remove.', 'Whisk orange juice, soy sauce, brown sugar, 1 tbsp cornstarch, and orange zest.', 'Pour into pan; cook until thickened, about 3 min.', 'Toss chicken in sauce; serve over rice.']::text[]),
  ('adc36445-2fc5-461a-a51f-89c9fc2280d4', 'Chicken Marsala', 'Chicken', '{}', '4', '15 min', '20 min', ARRAY['Dredge chicken in flour; cook in butter over medium-high 3–4 min per side. Remove.', 'Sauté mushrooms in same pan until golden.', 'Add Marsala wine; let reduce 2 min. Add broth; simmer 5 min.', 'Return chicken; simmer in sauce 5 min. Spoon sauce over chicken before serving.']::text[]),
  ('8caab153-3bee-4530-9a36-e9f5096d2b61', 'Chicken Burrito Bowl', 'Chicken', '{}', '4', '15 min', '20 min', ARRAY['Season chicken with taco seasoning; cook in a skillet until cooked through.', 'Slice or shred chicken.', 'Build bowls: rice base, then beans, corn, chicken.', 'Top with salsa, guacamole, cheese, and sour cream.']::text[]),
  ('54340a36-fbe7-4f9a-b832-9903135bfdb8', 'Chicken Quesadillas', 'Chicken', '{}', '4', '10 min', '15 min', ARRAY['Heat a skillet over medium.', 'Lay a tortilla in pan; top one half with chicken and cheese.', 'Fold over; cook 2–3 min per side until golden and cheese is melted.', 'Slice into wedges; serve with salsa, sour cream, and guacamole.']::text[]),
  ('79ae275d-5419-4111-a012-a708dfd50a52', 'White Chicken Chili', 'Chicken', '{}', '8', '10 min', '360 min', ARRAY['Add chicken, beans, chiles, broth, cumin, and garlic powder to slow cooker.', 'Cook on Low 6 hours or High 3 hours.', 'Shred chicken; stir in cream cheese and sour cream until smooth.', 'Serve with shredded cheese, jalapeño, and tortilla chips.']::text[]),
  ('4fe9c84b-eb71-4832-9766-49650f8cf1bf', 'Chicken Tortilla Soup', 'Chicken', '{}', '8', '10 min', '30 min', ARRAY['Combine all ingredients in a large pot.', 'Bring to boil; reduce heat and simmer 20 min.', 'Adjust seasoning with salt and pepper.', 'Serve topped with tortilla strips, sour cream, shredded cheese, and avocado.']::text[]),
  ('e0ff5e8b-78e4-4e84-bdf7-71ca9e23381a', 'Chicken Piccata', 'Chicken', '{}', '4', '10 min', '20 min', ARRAY['Dredge chicken in flour; cook in butter and olive oil 3–4 min per side. Remove.', 'Deglaze pan with wine; let reduce 1 min.', 'Add lemon juice and capers; swirl in remaining butter.', 'Return chicken; spoon sauce over. Serve with pasta or mashed potatoes.']::text[]),
  ('3dc17613-3c66-42f4-82c3-63c7329d6a96', 'Chicken Shawarma', 'Chicken', '{}', '4', '15 min', '25 min', ARRAY['Toss chicken with spices, lemon juice, and olive oil; marinate 30 min.', 'Grill or bake at 425°F for 20–25 min until cooked through.', 'Slice thin.', 'Serve in pita with tzatziki, tomato, cucumber, and onion.']::text[]),
  ('7bcbe48c-c3fc-4ecd-95f3-95a8cb97ec42', 'Bruschetta Chicken', 'Chicken', '{}', '4', '15 min', '20 min', ARRAY['Season chicken; grill or pan-sear 5–6 min per side until cooked through.', 'Mix tomatoes, garlic, basil, olive oil, salt, and pepper to make bruschetta.', 'Top each chicken breast with mozzarella; broil 2 min to melt.', 'Spoon bruschetta over chicken; drizzle with balsamic glaze.']::text[]),
  ('22e136a3-9fbc-43c1-806e-441b5a969a45', 'Chicken Stuffed Shells', 'Chicken', '{}', '6', '25 min', '35 min', ARRAY['Preheat oven to 375°F. Mix chicken, ricotta, egg, and 1 cup mozzarella.', 'Spread half the sauce in a baking dish.', 'Fill shells with chicken mixture; arrange over sauce.', 'Top with remaining sauce and mozzarella. Bake 30 min.']::text[]),
  ('43a2f4fe-15ab-4358-9eec-c0707ea6d576', 'Chicken Cobbler', 'Chicken', '{}', '8', '10 min', '55 min', ARRAY['Preheat oven to 375°F. Pour melted butter into a 9x13 baking dish.', 'Mix chicken, vegetables, cream of chicken, and broth; pour over butter — do NOT stir.', 'Mix biscuit dough (biscuit mix + milk); pour over the top — do NOT stir.', 'Bake 45–55 min until biscuit top is golden and center is set. Sprinkle seasoning packet over top at the end.']::text[]),
  ('340dee32-af04-433c-8a83-8427b346d607', 'General Tso''s Chicken', 'Chicken', '{}', '4', '20 min', '20 min', ARRAY['Coat chicken in cornstarch; fry in batches over medium-high until crispy and cooked, about 5 min per batch.', 'Whisk together soy sauce, hoisin, brown sugar, vinegar, and sesame oil.', 'In a clean pan, toast garlic and red pepper; add sauce, bring to simmer.', 'Toss chicken in sauce; serve over rice with steamed broccoli.']::text[]),
  ('6fa8d171-14f8-4535-88da-36ea097dcfbb', 'Chicken Divan', 'Chicken', '{}', '6', '15 min', '30 min', ARRAY['Preheat oven to 350°F.', 'Mix soup, mayo, sour cream, and 1 cup cheese.', 'Layer broccoli in a greased baking dish; top with chicken, then sauce mixture.', 'Mix remaining cheese with breadcrumbs; sprinkle over top. Bake 25–30 min until bubbly.']::text[]),
  ('70a55efa-fb59-40cd-b512-44976589f8b5', 'Rotisserie Chicken', 'Chicken', '{}', NULL, NULL, NULL, '{}'),
  ('4d37c682-03f5-4042-915a-75e758653c4d', 'Caprese Chicken', 'Chicken', '{}', '4', '10 min', '20 min', ARRAY['Season chicken; cook in olive oil over medium-high 5–6 min per side.', 'Top each breast with tomato slice and mozzarella; cover and cook 2 min until cheese melts.', 'Transfer to a plate; top with fresh basil.', 'Drizzle with balsamic glaze before serving.']::text[]),
  ('d512f2e7-ae92-480f-8773-77aaae8f8815', 'Chicken Caesar Wrap', 'Chicken', '{}', '4', '10 min', '15 min', ARRAY['Warm tortillas.', 'Toss romaine with Caesar dressing and parmesan.', 'Layer chicken and salad mixture onto each tortilla.', 'Fold in sides; roll up tightly. Cut in half.']::text[]),
  ('359a41b3-db24-4606-953c-db08970705b3', 'Chicken Ziti', 'Chicken', '{}', '6', '15 min', '35 min', ARRAY['Preheat oven to 375°F. Cook ziti; drain. Brown chicken; season.', 'Toss ziti with chicken, sauce, and ricotta if using.', 'Transfer to greased baking dish; top with mozzarella.', 'Bake 25 min until cheese is bubbly and golden.']::text[]),
  ('aa547c80-2c52-4c3f-ba5a-febc7c3ff40c', 'Baby Back Ribs', 'Pork', '{}', '4', '15 min', '180 min', ARRAY['Remove membrane from back of ribs. Mix dry rub; coat ribs generously.', 'Wrap racks in foil; bake at 275°F for 2.5 hours.', 'Unwrap; brush with BBQ sauce. Grill or broil 5–10 min until caramelized.', 'Rest 10 min; slice between bones.']::text[]),
  ('7aed3678-90e8-47e3-9a13-6dd2cc3fd6d8', 'Pork Tenderloin', 'Pork', '{}', '4', '10 min', '25 min', ARRAY['Preheat oven to 425°F. Rub tenderloin with olive oil, garlic, herbs, salt, and pepper.', 'Sear in an oven-safe skillet over high heat, 2 min per side.', 'Transfer to oven; roast 20–25 min until internal temp is 145°F.', 'Tent with foil, rest 10 min before slicing.']::text[]),
  ('63ed521a-f02f-4ded-b706-d4f3af7e4f3f', 'Pork Carnitas', 'Pork', '{}', '10', '10 min', '480 min', ARRAY['Season pork with cumin, chili powder, garlic powder, oregano, and salt.', 'Add to slow cooker with orange and lime juice; cook Low 8 hours.', 'Shred pork; spread on a sheet pan, pour some cooking liquid over.', 'Broil 5–7 min until edges are crispy. Serve in tortillas.']::text[]),
  ('5d04f77e-bdd5-4f97-8979-f07e07b2555c', 'Ham and Bean Soup', 'Pork', '{}', '8', '10 min', '60 min', ARRAY['Sauté onion, celery, and carrots in a large pot until softened.', 'Add ham, beans, and broth; bring to boil.', 'Reduce heat; simmer 45 min. Lightly mash some beans to thicken.', 'Season with salt and pepper.']::text[]),
  ('0f2e2b43-33e3-4f95-a275-7f83c681b5cc', 'Pork Fried Rice', 'Pork', '{}', '4', '10 min', '15 min', ARRAY['Heat oil in a large skillet or wok over high. Add pork; cook 2 min.', 'Push to side; scramble eggs.', 'Add rice and frozen vegetables; stir-fry 3–4 min.', 'Add soy sauce and sesame oil; toss to combine.']::text[]),
  ('a7578088-619b-403c-ae88-33748a07418c', 'Sausage and Peppers', 'Pork', '{}', '6', '10 min', '25 min', ARRAY['Brown sausage in a large skillet; slice into rounds or keep whole. Remove.', 'Cook peppers and onion in same pan until softened and slightly charred.', 'Return sausage; add marinara if making subs, or skip for a simple skillet.', 'Serve in hoagie rolls or over pasta.']::text[]),
  ('8f0098ae-a4aa-44b9-b1d7-bd964b7f86b2', 'Kielbasa and Cabbage', 'Pork', '{}', '6', '10 min', '25 min', ARRAY['Brown kielbasa in butter in a large skillet; remove.', 'Add onion; cook until softened. Add cabbage; cook 10 min until wilted.', 'Return kielbasa; stir in vinegar and caraway seeds.', 'Season with salt and pepper; cook 5 more min.']::text[]),
  ('3fd54f74-8820-4bf5-9a07-8ae06b55059e', 'Ham and Cheese Sliders', 'Pork', '{}', '12', '15 min', '20 min', ARRAY['Preheat oven to 350°F. Slice rolls in half horizontally keeping them connected.', 'Layer ham and cheese on bottom half; replace top.', 'Mix butter, Dijon, honey, Worcestershire, and poppy seeds; brush over rolls.', 'Cover with foil; bake 15 min. Uncover last 5 min until tops are golden.']::text[]),
  ('8ed52742-b09a-4207-a58e-c6fb76a13acd', 'Sausage and Potato Skillet', 'Pork', '{}', '4', '10 min', '25 min', ARRAY['Cook potatoes in oil in a large skillet over medium-high until browned, about 10 min.', 'Add bell pepper and onion; cook 5 min.', 'Add sausage; cook until browned through, about 8 min.', 'Season with garlic powder, paprika, salt, and pepper.']::text[]),
  ('2d65a71e-1dff-42d0-839c-07393fd598a2', 'Pork Al Pastor', 'Pork', '{}', '8', '20 min', '360 min', ARRAY['Blend chiles, garlic, pineapple juice, cumin, oregano, and achiote into a marinade.', 'Marinate pork overnight (or at least 2 hours).', 'Cook in slow cooker Low 6 hours OR sear on a hot grill/skillet until charred.', 'Serve in tortillas with pineapple chunks, cilantro, and diced onion.']::text[]),
  ('9f4075ca-0e5e-4428-aeec-c8426e67479b', 'Pork and Sauerkraut', 'Pork', '{}', '6', '5 min', '480 min', ARRAY['Place pork in slow cooker.', 'Pour sauerkraut over; add apples, brown sugar, and caraway seeds.', 'Cook on Low 8 hours until pork is very tender.', 'Serve with mashed potatoes or dumplings.']::text[]),
  ('cb32b7bb-7adf-4e7a-9ed9-910312fa80e5', 'Pork Chop Casserole', 'Pork', '{}', '4', '10 min', '60 min', ARRAY['Preheat oven to 350°F. Layer potatoes and onion in a greased baking dish; season.', 'Whisk cream of mushroom and broth; pour half over potatoes.', 'Nestle pork chops on top; pour remaining sauce over.', 'Cover with foil; bake 50–60 min until pork is cooked through and potatoes are tender.']::text[]),
  ('bf261b96-58a5-4910-847e-bb39682d4e9f', 'Bacon and Egg Fried Rice', 'Pork', '{}', '4', '10 min', '15 min', ARRAY['Cook bacon in a large skillet until crispy; remove, leave 2 tbsp drippings.', 'Scramble eggs in drippings; push to sides.', 'Add rice and peas; stir-fry 3–4 min.', 'Add soy sauce and bacon; toss. Garnish with green onions.']::text[]),
  ('e485bcee-da28-4f39-b5e5-97330afa0b88', 'Sausage Gravy Bake', 'Pork', '{}', '6', '15 min', '35 min', ARRAY['Preheat oven to 375°F. Brown sausage in an oven-safe skillet; do not drain.', 'Sprinkle flour over sausage; stir 1 min. Gradually whisk in milk; simmer until thickened.', 'Season with salt and plenty of black pepper.', 'Place biscuits on top of gravy; bake 20–25 min until biscuits are golden.']::text[]),
  ('e45e8751-c604-40b2-bc65-25e3a33f0c3d', 'Pork Schnitzel', 'Pork', '{}', '4', '20 min', '15 min', ARRAY['Season pork; dredge in flour, dip in egg, press firmly into breadcrumbs.', 'Heat oil and a tablespoon of butter in a large skillet over medium-high.', 'Fry schnitzels 2–3 min per side until deep golden and cooked through.', 'Drain on paper towels; serve immediately with lemon wedges and a green salad.']::text[]),
  ('fa6dc9fc-7ef1-486a-a56e-cc12cb63b1d4', 'Shrimp Tacos', 'Seafood', '{}', '4', '15 min', '10 min', ARRAY['Season shrimp with chili powder, cumin, garlic powder, salt.', 'Cook in a hot skillet with a little oil 2–3 min per side.', 'Warm tortillas; layer with coleslaw, shrimp, and avocado.', 'Drizzle with lime crema.']::text[]),
  ('63d63364-0f32-4f89-8a74-41026c93c2cc', 'Shrimp Fried Rice', 'Seafood', '{}', '4', '10 min', '15 min', ARRAY['Cook shrimp in a hot wok or skillet 2 min per side; remove.', 'Scramble eggs in same pan; push aside.', 'Add rice and vegetables; stir-fry 3–4 min.', 'Add soy sauce, sesame oil, and shrimp; toss together.']::text[]),
  ('7b8c0358-0281-4b66-81aa-5409a8c38506', 'Shrimp Scampi', 'Seafood', '{}', '4', '10 min', '15 min', ARRAY['Cook pasta; reserve ½ cup pasta water, drain.', 'Sauté garlic in butter 1 min; add shrimp, cook 2 min per side, remove.', 'Add wine; reduce 2 min. Add lemon juice and pasta water.', 'Toss with pasta; return shrimp. Garnish with parsley and parmesan.']::text[]),
  ('21f39ebf-267a-4493-96b4-b2c12056ef41', 'Salmon Dinner', 'Seafood', '{}', '4', '5 min', '15 min', ARRAY['Season salmon with salt, pepper, and dill.', 'Pan-sear skin-side up in butter over medium-high 4 min.', 'Flip; add garlic, baste with butter, cook 3–4 more min.', 'Squeeze lemon over; serve with roasted vegetables or rice.']::text[]),
  ('2ec3c1f8-4205-4cb4-bd32-636d58aa14bc', 'Tuna Noodle Casserole', 'Seafood', '{}', '6', '15 min', '30 min', ARRAY['Preheat oven to 375°F. Mix soup and milk; stir in tuna, noodles, peas, and half the cheese.', 'Transfer to greased baking dish; top with remaining cheese and breadcrumbs.', 'Bake 25–30 min until bubbly and topping is golden.']::text[]),
  ('757341e8-6194-4ff3-9c6b-de89914093fe', 'Fish and Chips', 'Seafood', '{}', '4', '15 min', '25 min', ARRAY['Cook fries per package or roast potatoes at 425°F until crispy.', 'Whisk flour, baking powder, and beer into a batter; season with salt.', 'Dip fish in batter; fry in 375°F oil 4–5 min until golden and cooked through.', 'Drain on paper towels; serve with fries, malt vinegar, and tartar sauce.']::text[]),
  ('6129e6a4-abb0-44c7-998b-4d9262aaf1b7', 'Clam Chowder', 'Seafood', '{}', '6', '15 min', '30 min', ARRAY['Cook bacon in a pot; remove, leave drippings. Sauté onion until soft.', 'Whisk flour into onion; gradually add clam juice and cream.', 'Add potatoes; simmer 15 min until tender.', 'Stir in clams and bacon; heat through. Season generously. Serve in bread bowls.']::text[]),
  ('4355f2bf-c404-4dbf-85b4-28ed357c6470', 'Crab Cakes', 'Seafood', '{}', '4', '20 min', '10 min', ARRAY['Gently mix crab, breadcrumbs, egg, mayo, and seasonings; do not over-mix.', 'Form 8 patties; refrigerate 30 min to firm up.', 'Pan-fry in butter over medium-high 3–4 min per side until golden.', 'Serve with tartar sauce and lemon.']::text[]),
  ('b6c4e830-36b7-4869-808e-34a34d1c8852', 'Lobster Rolls', 'Seafood', '{}', '4', '15 min', '10 min', ARRAY['Mix lobster with mayo, celery, lemon juice, salt, and pepper.', 'Butter outsides of buns; toast in a skillet until golden.', 'Fill buns generously with lobster salad.', 'Serve immediately with chips.']::text[]),
  ('eea2a578-ada0-48d2-9238-799e98dc87c7', 'Veggie Stir Fry', 'Vegetarian', '{}', '4', '15 min', '15 min', ARRAY['Stir together soy sauce, hoisin, and sesame oil.', 'If using tofu, crisp in a hot skillet first; remove.', 'Stir-fry vegetables and garlic in high heat 4–5 min until crisp-tender.', 'Return tofu if using; pour sauce over, toss 1 min. Serve over rice.']::text[]),
  ('7938fb14-9e58-4119-9e7b-cb4117f086d8', 'Pasta Primavera', 'Vegetarian', '{}', '4', '15 min', '20 min', ARRAY['Cook pasta; reserve ½ cup pasta water, drain.', 'Sauté garlic in olive oil; add vegetables, cook 6–8 min until tender.', 'Toss with pasta, adding pasta water to loosen.', 'Finish with parmesan and fresh basil.']::text[]),
  ('090beeb2-0505-4288-89e4-845bb2e8ccba', 'Black Bean Tacos', 'Vegetarian', '{}', '4', '10 min', '10 min', ARRAY['Warm beans in a skillet with cumin, chili powder, garlic powder, and a splash of water; mash slightly.', 'Warm tortillas.', 'Fill tortillas with beans; top with avocado, salsa, and cheese.', 'Finish with fresh cilantro and lime juice.']::text[]),
  ('116223ca-8055-4609-9e9e-c118236cfa56', 'Vegetable Curry', 'Vegetarian', '{}', '6', '15 min', '25 min', ARRAY['Sauté onion, garlic, and ginger in oil; stir in curry paste, cook 2 min.', 'Add tomatoes and coconut milk; bring to a simmer.', 'Add vegetables; cook 15–20 min until tender.', 'Serve over basmati rice with naan.']::text[]),
  ('9ff87333-4659-4362-9196-2061665c3de3', 'Eggplant Parmesan', 'Vegetarian', '{}', '6', '30 min', '40 min', ARRAY['Salt eggplant slices; let sit 30 min, then pat dry. Dip in egg, coat in breadcrumbs.', 'Pan-fry or bake at 400°F until golden on both sides.', 'Layer in a baking dish: marinara, eggplant, mozzarella. Repeat; top with parmesan.', 'Bake at 375°F for 25 min until bubbly.']::text[]),
  ('8941463f-c334-486e-a391-e1a5dac6dcb0', 'Stuffed Peppers (Vegetarian)', 'Vegetarian', '{}', '6', '20 min', '40 min', ARRAY['Preheat oven to 375°F.', 'Mix rice, beans, corn, salsa, and 1 cup cheese.', 'Stand peppers upright in a baking dish; fill with mixture; top with remaining cheese.', 'Add ¼ cup water to dish; cover with foil, bake 30 min. Uncover last 10 min.']::text[]),
  ('2405c63c-fdbc-4ce0-abd4-86083f62120b', 'Spaghetti Squash Marinara', 'Vegetarian', '{}', '4', '10 min', '45 min', ARRAY['Halve squash; scoop seeds, drizzle with olive oil, season, place cut-side down on a baking sheet.', 'Roast at 400°F for 40 min until tender.', 'Scrape flesh with a fork to form "spaghetti" strands.', 'Top with warmed marinara and parmesan.']::text[]),
  ('e508dfe5-041d-4cfc-a369-941bddff9565', 'Cauliflower Fried Rice', 'Vegetarian', '{}', '4', '10 min', '15 min', ARRAY['Sauté garlic in sesame oil over medium-high.', 'Add cauliflower rice; cook 5 min until softened and lightly browned.', 'Push to sides; scramble eggs in center.', 'Add peas and carrots; stir in soy sauce. Toss everything together.']::text[]),
  ('bcdf3f72-a56c-4fae-96a2-f3e58cbdbe9f', 'Pita and Hummus Board', 'Vegetarian', '{}', NULL, NULL, NULL, '{}'),
  ('997cac96-7a02-4210-99c8-6676cfe79920', 'Mac and Cheese', 'Other', '{}', '6', '10 min', '20 min', ARRAY['Cook macaroni; drain.', 'Melt butter in pot; whisk in flour, cook 1 min. Gradually whisk in milk; simmer until thickened.', 'Remove from heat; stir in cheddar until smooth. Add seasonings.', 'Fold in macaroni. Serve as-is or pour into a baking dish and broil with breadcrumb topping.']::text[]),
  ('86daa7e5-03c6-4ff9-8a99-e952656e205e', 'Grilled Cheese and Tomato Soup', 'Other', '{}', '4', '5 min', '15 min', ARRAY['Heat tomato soup with milk per can directions; keep warm.', 'Butter one side of each bread slice.', 'Build sandwiches butter-side out with 2 slices cheese each.', 'Grill in a skillet over medium, pressing lightly, 2–3 min per side until golden. Serve with soup for dipping.']::text[]),
  ('01574abf-f6a9-4f7f-9fd0-2e15bafa8d20', 'Waffles', 'Other', '{}', '4', '10 min', '20 min', ARRAY['Whisk dry ingredients. Mix milk, egg yolks, and butter; combine with dry.', 'Beat egg whites to stiff peaks; fold into batter.', 'Pour batter into preheated, greased waffle iron; cook until golden and crisp.', 'Serve with maple syrup, butter, and fresh berries.']::text[]),
  ('bca82a43-ca53-4815-9a16-0985c681da7d', 'Breakfast Burritos', 'Other', '{}', '4', '10 min', '15 min', ARRAY['Scramble eggs in a buttered skillet; season with salt and pepper.', 'Warm tortillas.', 'Layer eggs, sausage, cheese, and salsa on each tortilla.', 'Fold in sides; roll up tightly.']::text[]),
  ('c095c778-8d77-4dcf-9b14-f8a26335e5c1', 'Omelets', 'Other', '{}', '1', '5 min', '5 min', ARRAY['Whisk eggs with salt and pepper.', 'Melt butter in an 8-inch skillet over medium-high; pour in eggs.', 'As edges set, lift and tilt pan to let runny egg flow underneath.', 'When almost set, add fillings and cheese to one half; fold over. Slide onto plate.']::text[]),
  ('b0ad3ec7-9426-43ba-925b-08d39d8950ef', 'Quiche', 'Other', '{}', '8', '20 min', '45 min', ARRAY['Preheat oven to 375°F. Blind-bake crust 10 min.', 'Whisk eggs with cream, salt, and pepper.', 'Layer cheese, bacon, and vegetables in crust; pour egg mixture over.', 'Bake 35–40 min until set and lightly golden. Rest 10 min before slicing.']::text[]),
  ('401370b0-9871-49b2-88a0-2b0640e8e6ae', 'Nachos', 'Other', '{}', '6', '10 min', '10 min', ARRAY['Preheat oven to 375°F.', 'Spread chips in a single layer on a large baking sheet.', 'Top with beans, jalapeños, and cheese.', 'Bake 8–10 min until cheese is melted. Top with sour cream, salsa, and guacamole.']::text[]),
  ('f1dab506-0583-41a3-abdb-3abfff645758', 'Street Corn Quesadillas', 'Other', '{}', '4', '15 min', '15 min', ARRAY['Char corn in a skillet or under broiler; mix with cotija, chili powder, and paprika.', 'Spread chipotle mayo on tortilla; top half with corn mixture and Monterey Jack.', 'Fold; cook in a buttered skillet 2–3 min per side until golden.', 'Slice; serve with lime wedges.']::text[]),
  ('a78f2fc5-f97e-4976-bd38-95f10088c0c1', 'Bean and Cheese Burritos', 'Other', '{}', '4', '5 min', '10 min', ARRAY['Warm refried beans.', 'Microwave or warm tortillas.', 'Spread beans down the center; add cheese and a spoonful of salsa.', 'Fold in sides; roll up. Serve with extra salsa and sour cream.']::text[]),
  ('192437c5-2302-4867-be6e-4e9b9b5c99f7', 'Cobb Salad', 'Other', '{}', '4', '20 min', '0 min', ARRAY['Arrange romaine in a large bowl or platter.', 'Arrange chicken, bacon, eggs, avocado, tomatoes, and blue cheese in neat rows on top.', 'Serve with blue cheese or ranch dressing on the side.']::text[]),
  ('7e2ca4fc-78f4-46a8-b4ab-36c98dbb8157', 'Soup and Sandwich', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('d3fd4647-9e0d-466f-b07d-df981beb574b', 'Hotdogs and Fries', 'Other', '{}', '4', '5 min', '20 min', ARRAY['Bake frozen fries per package directions.', 'Grill, boil, or pan-fry hot dogs until heated through.', 'Toast buns if desired.', 'Serve with desired toppings and fries on the side.']::text[]),
  ('a8c59b4b-e1c9-45e3-83f1-8ea2db735e0b', 'Egg Rolls', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('2d9c81de-861e-4d14-92fc-bb937661c2c8', 'Meatball Subs', 'Other', '{}', '4', '15 min', '25 min', ARRAY['Simmer meatballs in marinara sauce 15–20 min until heated through.', 'Split rolls; pile 4–5 meatballs with sauce into each.', 'Top with provolone and parmesan.', 'Broil 3 min until cheese is bubbly.']::text[]),
  ('ab5efca7-b90b-40f7-9b11-3c357f6de3eb', 'Fettuccine Alfredo', 'Other', '{}', '4', '5 min', '20 min', ARRAY['Cook fettuccine; reserve 1 cup pasta water, drain.', 'Melt butter over medium; sauté garlic 1 min.', 'Add cream; simmer 5 min until slightly thickened.', 'Remove from heat; stir in parmesan. Toss with pasta, adding pasta water to adjust consistency.']::text[]),
  ('3b7281cf-47bc-4734-bf75-826619433ae9', 'Breakfast for Dinner', 'Other', '{}', NULL, NULL, NULL, '{}'),
  ('c9d2d1b0-2521-47b5-ae46-0379831e00c9', 'Loaded Baked Potatoes', 'Other', '{}', '4', '5 min', '60 min', ARRAY['Scrub potatoes; rub with oil and salt. Pierce several times with a fork.', 'Bake at 400°F for 55–60 min until tender.', 'Cut open and fluff inside with a fork.', 'Load with cheddar, sour cream, bacon, and green onions.']::text[]);
